20	impl<D: AsDiagnostic + ?Sized> fmt::Display for PrintGitHubDiagnostic<'_, D> {
21	    fn fmt(&self, fmt: &mut fmt::Formatter<'_>) -> io::Result<()> {
22	        let diagnostic = self.diag.as_diagnostic();
23	        let location = diagnostic.location();
24	
25	        // Docs:
26	        // https://docs.github.com/en/actions/using-workflows/workflow-commands-for-github-actions
27	
28	        let Some(span) = location.span else {
29	            return Ok(());
30	        };
31	        let Some(source_code) = location.source_code else {
32	            return Ok(());
33	        };
34	
35	        let file_name_unescaped = match &location.resource {
36	            Some(Resource::File(file)) => file,
37	            _ => return Ok(()),
38	        };
39	
40	        let source = SourceFile::new(source_code);
41	        let start = source.location(span.start())?;
42	        let end = source.location(span.end())?;
43	
44	        let command = match diagnostic.severity() {
45	            Severity::Error | Severity::Fatal => "error",
46	            Severity::Warning => "warning",
47	            Severity::Hint | Severity::Information => "notice",
48	        };
49	
50	        let title = {
51	            let mut message = MarkupBuf::default();
52	            let mut fmt = fmt::Formatter::new(&mut message);
53	            fmt.write_markup(markup!({ PrintDiagnosticMessage(diagnostic) }))?;
54	            markup_to_string(&message)
55	        };
56	
57	        fmt.write_str(
58	            format! {
59	                "::{} file={},line={},endLine={},col={},endColumn={}::{}",
60	                command, // constant, doesn't need escaping
61	                escape_property(file_name_unescaped),
62	                start.line_number, // integer, doesn't need escaping
63	                end.line_number, // integer, doesn't need escaping
64	                start.column_number, // integer, doesn't need escaping
65	                end.column_number, // integer, doesn't need escaping
66	                title.map_or_else(String::new, escape_data),
67	            }
68	            .as_str(),
69	        )?;
70	
71	        Ok(())
72	    }
73	}
