123	fn markup_to_string(markup: &MarkupBuf) -> Option<String> {
124	    let mut buffer = Vec::new();
125	    let mut write = fmt::Termcolor(termcolor::NoColor::new(&mut buffer));
126	    let mut fmt = fmt::Formatter::new(&mut write);
127	    fmt.write_markup(markup! { {markup} }).ok()?;
128	    String::from_utf8(buffer).ok()
129	}
