25	/// Handler for the "ci" command of the Biome CLI
26	pub(crate) fn ci(session: CliSession, payload: CiCommandPayload) -> Result<(), CliDiagnostic> {
27	    let CiCommandPayload {
28	        cli_options,
29	        formatter_enabled,
30	        linter_enabled,
31	        organize_imports_enabled,
32	        configuration,
33	        mut paths,
34	        since,
35	        changed,
36	    } = payload;
37	    setup_cli_subscriber(cli_options.log_level, cli_options.log_kind);
38	
39	    let loaded_configuration =
40	        load_configuration(&session.app.fs, cli_options.as_configuration_path_hint())?;
41	
42	    validate_configuration_diagnostics(
43	        &loaded_configuration,
44	        session.app.console,
45	        cli_options.verbose,
46	    )?;
47	    resolve_manifest(&session)?;
48	
49	    let LoadedConfiguration {
50	        configuration: mut fs_configuration,
51	        directory_path: configuration_path,
52	        ..
53	    } = loaded_configuration;
54	    let formatter = fs_configuration
55	        .formatter
56	        .get_or_insert_with(PartialFormatterConfiguration::default);
57	
58	    if formatter_enabled.is_some() {
59	        formatter.enabled = formatter_enabled;
60	    }
61	
62	    let linter = fs_configuration
63	        .linter
64	        .get_or_insert_with(PartialLinterConfiguration::default);
65	
66	    if linter_enabled.is_some() {
67	        linter.enabled = linter_enabled;
68	    }
69	
70	    let organize_imports = fs_configuration
71	        .organize_imports
72	        .get_or_insert_with(PartialOrganizeImports::default);
73	
74	    if organize_imports_enabled.is_some() {
75	        organize_imports.enabled = organize_imports_enabled;
76	    }
77	
78	    // no point in doing the traversal if all the checks have been disabled
79	    if fs_configuration.is_formatter_disabled()
80	        && fs_configuration.is_linter_disabled()
81	        && fs_configuration.is_organize_imports_disabled()
82	    {
83	        return Err(CliDiagnostic::incompatible_end_configuration("Formatter, linter and organize imports are disabled, can't perform the command. This is probably and error."));
84	    }
85	
86	    if let Some(mut configuration) = configuration {
87	        if let Some(linter) = configuration.linter.as_mut() {
88	            // Don't overwrite rules from the CLI configuration.
89	            // Otherwise, rules that are disabled in the config file might
90	            // become re-enabled due to the defaults included in the CLI
91	            // configuration.
92	            linter.rules = None;
93	        }
94	        fs_configuration.merge_with(configuration);
95	    }
96	
97	    // check if support of git ignore files is enabled
98	    let vcs_base_path = configuration_path.or(session.app.fs.working_directory());
99	    let (vcs_base_path, gitignore_matches) =
100	        fs_configuration.retrieve_gitignore_matches(&session.app.fs, vcs_base_path.as_deref())?;
101	
102	    if since.is_some() && !changed {
103	        return Err(CliDiagnostic::incompatible_arguments("since", "changed"));
104	    }
105	
106	    if changed {
107	        paths = get_changed_files(&session.app.fs, &fs_configuration, since)?;
108	    }
109	
110	    session
111	        .app
112	        .workspace
113	        .register_project_folder(RegisterProjectFolderParams {
114	            path: session.app.fs.working_directory(),
115	            set_as_current_workspace: true,
116	        })?;
117	
118	    session
119	        .app
120	        .workspace
121	        .update_settings(UpdateSettingsParams {
122	            configuration: fs_configuration,
123	            workspace_directory: session.app.fs.working_directory(),
124	            vcs_base_path,
125	            gitignore_matches,
126	        })?;
127	
128	    execute_mode(
129	        Execution::new_ci().set_report(&cli_options),
130	        session,
131	        &cli_options,
132	        paths,
133	    )
134	}
